const payload = $json.body || $json;
const data = Array.isArray(payload.data) ? payload.data[0] : (payload.data || {});
const key = data.key || {};
const message = data.message || {};

// 1. Extrair e normalizar fromMe
const fromMe = Boolean(key.fromMe);

// 2. Extrair remoteJid
const remoteJid = key.remoteJid || key.remoteJidAlt || '';

// 3. Identificar grupos e status broadcasts
const isGroup = remoteJid.endsWith('@g.us');
const isStatus = remoteJid.includes('broadcast') || remoteJid === 'status@broadcast';

// 4. Detectar áudio / notas de voz
const isAudio = Boolean(message.audioMessage || data.messageType === 'audioMessage');

// 5. Extrair texto de qualquer formato Baileys/Evolution API
let userMessage = '';
if (typeof message === 'string') {
  userMessage = message;
} else if (message && typeof message === 'object') {
  userMessage = 
    message.conversation ||
    message.extendedTextMessage?.text ||
    message.imageMessage?.caption ||
    message.videoMessage?.caption ||
    message.documentMessage?.caption ||
    message.buttonsResponseMessage?.selectedDisplayText ||
    message.buttonsResponseMessage?.selectedButtonId ||
    message.listResponseMessage?.singleSelectReply?.selectedRowId ||
    message.listResponseMessage?.title ||
    message.templateButtonReplyMessage?.selectedId ||
    message.templateButtonReplyMessage?.selectedDisplayText ||
    message.reactionMessage?.text ||
    '';
}

userMessage = (userMessage || '').trim();

// 6. Extrair instância, servidor, apikey, nome e telefone limpo (100% dinâmico)
const instance = payload.instance || data.instanceId || payload.instanceId || data.instance || payload.sender || '';
const serverUrl = 'https://evolution.88barber.top';
const apiKey = '88barber-evolution-pbzJxGX3Ih2OHMKo';
const pushName = data.pushName || payload.pushName || 'Cliente';
const phone = remoteJid.replace('@s.whatsapp.net', '').replace('@g.us', '').replace(/\D/g, '');
const event = payload.event || '';

// 7. Regra de validação: mensagem real, 1:1, recebida (texto ou áudio)
const isValid = !fromMe && !isGroup && !isStatus && (userMessage.length > 0 || isAudio);

let reason = 'OK';
if (fromMe) reason = 'Mensagem enviada por mim (fromMe: true)';
else if (isGroup) reason = 'Mensagem de grupo ignorada';
else if (isStatus) reason = 'Status / Broadcast ignorado';
else if (!isAudio && userMessage.length === 0) reason = 'Mensagem sem texto ou evento sem conteúdo';

return {
  isValid,
  isAudio,
  reason,
  userMessage,
  rawMessage: data || payload,
  remoteJid,
  phone,
  pushName,
  instance,
  serverUrl,
  apiKey,
  fromMe,
  event,
  messageType: data.messageType || (isAudio ? 'audioMessage' : 'conversation')
};

